(()=>{
const $=id=>document.getElementById(id), status=$('accountStatus');
async function request(url, data){const response=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw Error(result.error?.message||result.error||result.message||'Please try again.');return result}
async function load(){try{const state=await request('/api/account');$('signIn').hidden=!state.ready||!!state.user;$('dashboard').hidden=!state.user;if(!state.ready){status.textContent='Account sign-in is being connected. Please check back shortly.';return}status.textContent=state.billingWarning||'';if(!state.user)return;$('accountEmail').textContent=state.user.email;const b=state.billing;$('credits').textContent=b?.remaining??0;$('subscriptionStatus').textContent=b?.status==='unavailable'?'Subscription status could not be refreshed. Please try again shortly.':b?.status==='approval_pending'?'Finish approving your subscription with PayPal.':b?.status==='payment_pending'?'Your PayPal payment confirmation is pending. Refresh this page in a moment.':b?.status==='active'?'US$4.99/month · 10 conversions per month':b?.status&&b.status!=='none'?`Subscription status: ${b.status}. Manage your payment details below.`:'No active subscription.';$('renewal').textContent=b?.periodEnd?`${b.cancelAtPeriodEnd?'Access ends':'Current billing month ends'} ${new Date(b.periodEnd).toLocaleDateString()}.`:'';const hasSubscription=!!(b&&(b.periodId||!['none','cancelled','expired'].includes(b.status)));$('subscribe').hidden=!state.stripeReady||hasSubscription;$('paypalSubscribe').hidden=!state.paypalReady||(hasSubscription&&b?.status!=='approval_pending');$('paypalSubscribe').textContent=b?.status==='approval_pending'?'Continue with PayPal · US$4.99/month':'Subscribe with PayPal · US$4.99/month';$('manage').hidden=!state.stripeReady||!b?.customer||b?.provider==='paypal';$('paypalManage').hidden=b?.provider!=='paypal'||!b?.customer;if(!state.billingReady)status.textContent='Your account is ready. Subscriptions are still being connected.';else if(new URLSearchParams(location.search).get('checkout')==='success'&&!b?.periodId)status.textContent='Payment confirmation is pending. Refresh this page in a moment.';}catch(error){status.textContent=error.message}}
$('signInForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await request('/api/auth/sign-in/magic-link',{email:$('email').value,callbackURL:'/account/',newUserCallbackURL:'/account/',errorCallbackURL:'/account/?error=link'});status.textContent='Check your inbox for your sign-in link. It expires in 10 minutes.';}catch(error){status.textContent=error.message}finally{button.disabled=false}});
for(const [id,action] of [['subscribe','checkout'],['manage','portal'],['paypalSubscribe','paypal-checkout'],['paypalManage','paypal-portal']])$(id).addEventListener('click',async()=>{$(id).disabled=true;try{const data=await request('/api/account',{action});location.assign(data.url)}catch(error){status.textContent=error.message;$(id).disabled=false}});
$('signOut').addEventListener('click',async()=>{try{await request('/api/auth/sign-out',{});await load()}catch(error){status.textContent=error.message}});
load().then(()=>{if(new URLSearchParams(location.search).has('error'))status.textContent='That sign-in link has expired or was already used. Request a new link below.'});
})();
